import os, re, sys
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SRC = os.path.join(ROOT, "archive", "04OCT26", "book")
OUT = os.path.join(ROOT, "book")
def rd(n): return open(os.path.join(SRC, n), encoding="utf-8").read().split("\n")
L1, L2, L3, LA = rd("01_chapter1.md"), rd("02_chapter2.md"), rd("03_chapter3.md"), rd("05_appendix.md")

class Rec:
    def __init__(self, lines): self.L = lines; self.B = []
    def K(self, a, b, *subs):
        t = "\n".join(self.L[a-1:b]).strip("\n")
        for old, new in subs:
            if old not in t: raise SystemExit(f"ไม่พบข้อความที่จะแทน ({a}-{b}): {old[:50]}")
            t = t.replace(old, new)
        self.B.append(t)
    def T(self, s): self.B.append(s.strip("\n"))
    def out(self): return "\n\n".join(self.B) + "\n"
def ext(L, a, b, *subs):
    t = "\n".join(L[a-1:b]).strip("\n")
    for old, new in subs:
        if old not in t: raise SystemExit(f"ไม่พบข้อความที่จะแทน ({a}-{b}): {old[:50]}")
        t = t.replace(old, new)
    return t
def chk(L, n, start):
    if not L[n-1].startswith(start): raise SystemExit(f"บรรทัด {n} ไม่ขึ้นต้นด้วย {start!r}: {L[n-1][:40]!r}")

