def edit(L, repl, delete=()):
    out = []
    for i, line in enumerate(L, 1):
        if i in delete:
            continue
        if i in repl: line = repl[i]
        out.append(line)
    t = "\n".join(out)
    t = re.sub(r"\n{3,}", "\n\n", t)
    return t
